/* 11 diff table and 12 records share the grid table */
.gt{overflow-x:auto;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.gt-in{min-width:640px}
.gt-row{display:grid;align-items:center;border-bottom:1px solid var(--line);font-size:13px;position:relative;background:var(--panel);transition:background-color .3s ease}
.gt-row>div{padding:10px 14px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.gt-head{position:sticky;top:0;z-index:2}
.gt-head>div{font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted)}
.gt-body .gt-row:hover{background:rgba(var(--fg-rgb),.015)}
.diff-cols{grid-template-columns:minmax(160px,1.3fr) 1fr 1fr 1fr}
.scan-bar{position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--accent);opacity:0;transition:opacity .25s}
.gt-row.scanning{background:var(--accent-bg)}
.gt-row.scanning .scan-bar{opacity:1}
.cell-diff{display:inline-flex;align-items:center;gap:6px;max-width:100%}
.old{text-decoration:line-through;color:var(--danger);background:rgba(255,90,95,.08);padding:0 4px;transition:opacity .3s,max-width .45s var(--ease);max-width:200px;overflow:hidden;white-space:nowrap}
.new{color:var(--success);background:rgba(62,207,142,.08);padding:0 4px;opacity:0;transform:translateX(-4px);transition:opacity .35s,transform .45s var(--ease)}
.cell-diff.show .new{opacity:1;transform:none}
.cell-diff.accepted .old{opacity:0;max-width:0;padding:0}
.cell-diff.accepted .new{background:transparent;color:var(--text)}
.cell-diff.rejected .new{opacity:0;max-width:0;padding:0}
.cell-diff.rejected .old{text-decoration:none;color:var(--text);background:transparent}
.diff-foot{display:flex;align-items:center;justify-content:space-between;padding:12px 14px;gap:10px;flex-wrap:wrap}
.diff-foot .btn{padding:8px 14px;font-size:13px}
.diff-title{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line);font-weight:600;font-size:14px}

.rec-cols{grid-template-columns:40px minmax(200px,1.5fr) minmax(200px,1.4fr) 140px 170px minmax(160px,1fr)}
.rec-scroll{max-height:440px;overflow:auto;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.rec-scroll .gt-in{min-width:960px}
.sortable{display:inline-flex;align-items:center;gap:4px;cursor:pointer;transition:color .25s}
.sortable:hover,.sortable.on{color:var(--text)}
.sortable .ms{font-size:14px;opacity:0;transition:opacity .25s,transform .35s var(--ease)}
.sortable.on .ms{opacity:1}
.sortable.desc .ms{transform:rotate(180deg)}
.co{display:flex;align-items:center;gap:10px}
.av{width:24px;height:24px;flex:none;display:grid;place-items:center;font-family:var(--mono);font-weight:700;font-size:11px;border:1px solid var(--icon-line);background:var(--icon-bg)}
.co b{font-weight:600}
.co span{color:var(--muted)}
.tags{display:flex;gap:4px}
.strength{display:flex;align-items:center;gap:8px}
.strength .segs i{width:10px;height:6px}
.strength .segs.s4 i{background:var(--success)}
.strength .segs.s0 i,.strength .segs i.off{background:var(--line)}
.lnk{color:var(--text-dim);text-decoration:none;border-bottom:1px solid var(--line);transition:color .25s,border-color .25s}
.lnk:hover{color:var(--accent);border-color:var(--accent)}
.cb{width:14px;height:14px;border:1px solid var(--icon-line);display:grid;place-items:center;transition:background-color .2s,border-color .2s;color:#120a02}
.cb .ms{font-size:12px;opacity:0;transition:opacity .2s}
.cb.on{background:var(--accent);border-color:var(--accent)}
.cb.on .ms{opacity:1}
.gt-row.sel{background:var(--accent-bg)}
.rec-foot-row{display:grid;font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted)}
.rec-foot-row>div{padding:10px 14px}

/* ---------- 12 records table ---------- */
{
  const rt = $('#rt');
  const lvl = ['No contact','Very weak','Weak','Strong','Very strong'];
  const data = [
    ['Northwind Labs','London',['Fintech','Series A','B2B'],2,4],
    ['Fieldnote','Berlin',['SaaS','Seed'],9,3],
    ['Quarry','Austin',['AI','Series B','B2B'],34,2],
    ['Halcyon Pay','Dublin',['Fintech','Series B'],5,4],
    ['Lumen Health','Boston',['Health','Series A','B2C'],61,1],
    ['Orbitly','Toronto',['SaaS','Series A'],14,3],
    ['Parcel AI','San Francisco',['AI','Seed'],0,0],
    ['Tessellate','Amsterdam',['Design','B2B'],21,2],
    ['Kitebase','Lisbon',['Dev tools','Series A','B2B'],3,4],
    ['Meridian Bank','Zurich',['Fintech','Enterprise'],120,1],
    ['Sable','New York',['Commerce','Series C'],45,2],
    ['Driftwood','Melbourne',['Travel','Seed','B2C'],7,3]
  ].map(r => ({ name:r[0], city:r[1], tags:r[2], days:r[3], s:r[4], url:r[0].toLowerCase().replace(/[^a-z]/g,'') + '.example.com', sel:false }));
  const when = d => d.s === 0 ? 'Never' : d.days === 0 ? 'Today' : d.days === 1 ? 'Yesterday' : d.days < 30 ? d.days + ' days ago' : d.days < 60 ? 'About a month ago' : Math.round(d.days / 30) + ' months ago';
  let sortKey = null, dir = 1;
  rt.innerHTML = `<div class="gt-row gt-head rec-cols"><div><span class="cb" id="rt-all">${ic('check')}</span></div><div><span class="sortable" data-k="name">Company${ic('arrow_upward')}</span></div><div>Categories</div><div><span class="sortable" data-k="days">Last contact${ic('arrow_upward')}</span></div><div><span class="sortable" data-k="s">Connection${ic('arrow_upward')}</span></div><div>Website</div></div><div class="gt-body" id="rt-body"></div><div class="rec-foot-row rec-cols" id="rt-foot"></div>`;
  const body = $('#rt-body');
  data.forEach(d => {
    const el = document.createElement('div'); el.className = 'gt-row rec-cols';
    el.innerHTML = `<div><span class="cb">${ic('check')}</span></div><div class="co"><span class="av">${d.name[0]}</span><b>${d.name}</b><span>${d.city}</span></div><div class="tags">${d.tags.slice(0,2).map(t => `<span class="tag">${t}</span>`).join('')}${d.tags.length > 2 ? `<span class="tag more">+${d.tags.length - 2}</span>` : ''}</div><div style="color:var(--text-dim)">${when(d)}</div><div class="strength"><span class="segs s${d.s}">${[0,1,2,3].map(n => `<i class="${n < d.s ? '' : 'off'}" style="${n < d.s && d.s < 4 ? 'background:var(--accent)' : ''}"></i>`).join('')}</span><span class="mono-xs" style="font-size:10px">${lvl[d.s]}</span></div><div>${d.s ? `<a class="lnk" href="#" onclick="return false">${d.url}</a>` : '<span style="color:var(--muted)">None</span>'}</div>`;
    el.querySelector('.cb').addEventListener('click', () => { d.sel = !d.sel; paintSel(); Sound.play('tick'); });
    d.el = el; body.appendChild(el);
  });
  function paintSel(){
    data.forEach(d => { d.el.classList.toggle('sel', d.sel); d.el.querySelector('.cb').classList.toggle('on', d.sel); });
    const n = data.filter(d => d.sel).length;
    $('#rt-all').classList.toggle('on', n === data.length);
    const avg = Math.round(data.reduce((a, d) => a + d.s, 0) / data.length / 4 * 100);
    $('#rt-foot').innerHTML = `<div></div><div>${n ? n + ' selected' : data.length + ' records'}</div><div></div><div></div><div>${avg}% average</div><div>${data.filter(d => d.s).length} links</div>`;
  }
  $('#rt-all').addEventListener('click', () => { const all = !data.every(d => d.sel); data.forEach(d => d.sel = all); paintSel(); Sound.play('select'); });
  $$('.sortable', rt).forEach(s => s.addEventListener('click', () => {
    const k = s.dataset.k; dir = sortKey === k ? -dir : (k === 's' ? -1 : 1); sortKey = k;
    $$('.sortable', rt).forEach(x => { x.classList.toggle('on', x === s); x.classList.toggle('desc', x === s && dir < 0); });
    const first = new Map(data.map(d => [d, d.el.getBoundingClientRect().top]));
    data.sort((a, b) => (typeof a[k] === 'string' ? a[k].localeCompare(b[k]) : a[k] - b[k]) * dir);
    data.forEach(d => body.appendChild(d.el));
    if (!reduce){
      data.forEach(d => { const dy = first.get(d) - d.el.getBoundingClientRect().top; d.el.style.transition = 'none'; d.el.style.transform = dy ? `translateY(${dy}px)` : ''; });
      raf2(() => data.forEach(d => { d.el.style.transition = 'transform .6s var(--ease), background-color .3s ease'; d.el.style.transform = ''; }));
    }
    Sound.play('tab');
  }));
  paintSel();
}
